121	
122		// 缺口期间新买单仍按既有规则拒绝（与亏损保护无关）；拒绝记录固化开日后的
123		// 风险快照（净值 1000、亏损 0、未限制），且不产生触线或撤单记录。
124		if _, err := e.Buy("A", 1, 10); err == nil {
125			t.Fatal("缺口期间新买单必须拒绝")
126		}
127		gapReject := e.Records()[len(e.Records())-1]
128		if gapReject.Kind != RecordRejected || !strings.Contains(gapReject.Reason, "缺口") {
129			t.Fatalf("缺口拒单必须留下缺口原因的拒绝记录: %+v", gapReject)
130		}
131		if gapReject.QuoteSeq != 1 || gapReject.QuoteMoment != 10 || gapReject.QuotePrice != 10 {
132			t.Fatalf("拒绝记录报价快照应停留在 seq1: %+v", gapReject)
133		}
134		if gapReject.RiskDay != 1 || gapReject.RiskBaseline != 1000 || gapReject.RiskEquity != 1000 ||
135			gapReject.RiskLoss != 0 || gapReject.RiskLimit != 90 || gapReject.RiskRestrict {
136			t.Fatalf("拒绝记录应固化开日时未触线的风险快照: %+v", gapReject)
137		}
138		if e.Cash() != 900 || e.ReservedCash() != 50 {
139			t.Fatalf("缺口拒单不得改动资金占用: cash=%d reserved=%d", e.Cash(), e.ReservedCash())
140		}
141	
142		// 补齐 seq2@(20,10)：链为 seq2@10（净值 1000，不触线）→ seq3@1（净值 910，
143		// 亏损恰好 90 达到上限，触线），两条一次依次生效。
144		recsBeforeGap := len(e.Records())
145		n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 20, Price: 10})
146		if err != nil {
147			t.Fatalf("补齐缺口必须成功: %v", err)
148		}
149		if n != 2 {
150			t.Fatalf("seq2 与等待中的 seq3 应一次依次生效，实际生效 %d 条", n)
151		}
152	
153		// 保护在刚开启的交易日触发：基准仍为开日时的 1000，当前净值 910、亏损 90。
154		st = e.RiskStatus()
155		if !st.Open || st.Day != 1 || st.Baseline != 1000 || st.LossLimit != 90 {
156			t.Fatalf("开日基准与上限必须保留: %+v", st)
157		}
158		if !st.Restricted || st.Equity != 910 || st.Loss != 90 {
159			t.Fatalf("seq3@1 生效后净值应为 910、亏损恰好 90 并已限制: %+v", st)
160		}
161		q, _ := e.CurrentQuote("A")
162		if q.Seq != 3 || q.Moment != 30 || q.Price != 1 {
163			t.Fatalf("最新报价应推进到 seq3@(30,1): %+v", q)
164		}
165		if e.HasGap("A") {
166			t.Fatal("补齐后不得再报告缺口")
167		}
168	
169		// 撤销买单剩余 5 股并释放 50 现金占用；现金余额与已入账的 10 股持仓保留。
170		ob, _ := e.Order(buyID)
171		if ob.Status != StatusCanceled || ob.Qty != 15 || ob.Filled != 10 || ob.Remaining() != 0 {
172			t.Fatalf("买单应只撤销未成交的 5 股、已成交 10 股保留: %+v", ob)
173		}
174		if !strings.Contains(ob.Reason, "亏损 90") || !strings.Contains(ob.Reason, "上限 90") {
175			t.Fatalf("撤单原因必须固化触线时亏损 90 与上限 90: %q", ob.Reason)
176		}
177		if e.Cash() != 900 || e.ReservedCash() != 0 || e.AvailableCash() != 900 ||
178			e.Position("A") != 10 {
179			t.Fatalf("撤单只释放占用：余额 900 与持仓 10 不变，占用归零: cash=%d reserved=%d available=%d pos=%d",
180				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"))
181		}
182	
183		// 卖单仍有效，可卖数量仍为 7。
184		os, _ := e.Order(sellID)
185		if os.Status != StatusPending || os.Qty != 3 || os.Limit != 1 || os.Remaining() != 3 {
186			t.Fatalf("卖单必须保持有效: %+v", os)
187		}
188		if e.Sellable("A") != 7 {
189			t.Fatalf("卖单占用的 3 股持仓必须保留，可卖数量仍为 7: %d", e.Sellable("A"))
190		}
191	
192		// 本批只新增“当日首次触线 + 撤销买单”共 2 条记录。
193		newRecs := e.Records()[recsBeforeGap:]
194		if len(newRecs) != 2 {
195			t.Fatalf("补齐应只新增 2 条记录（1 触线 + 1 撤单），实际 %d 条", len(newRecs))
196		}
197		trig := newRecs[0]
198		if trig.Kind != RecordRiskTriggered {
199			t.Fatalf("第一条新增记录必须是触线记录: %+v", trig)
200		}
201		if trig.RiskTrigger != RiskTriggerQuote || trig.RiskRefSeq != 3 || trig.RiskRefMoment != 30 {
202			t.Fatalf("触线必须由报价引发并关联 seq3 及其时刻 30: trigger=%s ref=%d moment=%d",
203				trig.RiskTrigger, trig.RiskRefSeq, trig.RiskRefMoment)
204		}
205		if trig.RiskDay != 1 || trig.RiskBaseline != 1000 || trig.RiskEquity != 910 ||
206			trig.RiskLoss != 90 || trig.RiskLimit != 90 || !trig.RiskRestrict {
207			t.Fatalf("触线快照必须固化 seq3@1 下的净值 910、亏损 90: %+v", trig)
208		}
209		if len(trig.RiskQuoteRefs) != 1 ||
210			trig.RiskQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 3, Moment: 30, Price: 1}) {
211			t.Fatalf("触线估值报价定位必须锚定 seq3@(30,1): %+v", trig.RiskQuoteRefs)
212		}
213		cr := newRecs[1]
214		if cr.Kind != RecordCanceled || cr.OrderID != buyID || cr.Filled != 10 || cr.Remaining != 5 {
215			t.Fatalf("第二条记录必须是撤销买单剩余 5 股、已成交 10 股: %+v", cr)
216		}
217		if cr.QuoteSeq != 3 || cr.QuoteMoment != 30 || cr.QuotePrice != 1 {
218			t.Fatalf("撤单报价快照应锚定触线时的 seq3@(30,1): %+v", cr)
219		}
220		if cr.RiskEquity != 910 || cr.RiskLoss != 90 || cr.RiskLimit != 90 || !cr.RiskRestrict {
221			t.Fatalf("撤单记录应携带触线时风险快照: %+v", cr)
222		}
223		if countRiskRecords(e) != 1 {
224			t.Fatal("一个交易日只能有一条触线记录")
225		}
226	
227		// 原成交记录保留成交时的报价（seq1@(10,10)）与成交价，不随开日或补齐改写；
228		// 成交发生在开日前，也不得事后补写风险快照。
229		var fillRec Record
230		for _, r := range e.Records() {
231			if r.Kind == RecordFilled && r.TradeID == 1 {
232				fillRec = r
233			}
234		}
235		if fillRec.TradeID != 1 {
236			t.Fatal("必须能找到成交编号 1 的原成交记录")
237		}
238		if !fillRec.QuoteValid || fillRec.QuoteSeq != 1 || fillRec.QuoteMoment != 10 || fillRec.QuotePrice != 10 {
239			t.Fatalf("原成交记录的报价快照必须保留成交时的 seq1@(10,10): %+v", fillRec)
240		}
241		if fillRec.TradePrice != 10 || fillRec.Qty != 10 || fillRec.Filled != 10 {
242			t.Fatalf("原成交记录的成交内容必须保留: %+v", fillRec)
243		}
244		if fillRec.RiskDay != 0 || fillRec.RiskRestrict {
245			t.Fatalf("开日前的成交记录不得被事后补写风险快照: %+v", fillRec)
246		}
247	
248		// 限制保留：补齐缺口后新买单仍被拒绝。
249		if _, err := e.Buy("A", 1, 1); err == nil {
250			t.Fatal("保护触发后新买单必须拒绝")
251		}
252	}
253	
254	// TestRiskStartDayInvalidParamsPreserveGapAndOrders 覆盖开日参数失败边界：
255	// 非正日号、负亏损上限都必须返回错误且不留记录，未开日状态、订单、两类占用与
256	// 等待报价原样保留；修正参数后合法开日与补齐仍按主路径行为处理。
257	func TestRiskStartDayInvalidParamsPreserveGapAndOrders(t *testing.T) {
258		e, buyID, sellID := startDayGapSetup(t)
259	
260		for _, tc := range []struct {
261			name      string
262			day       int64
263			lossLimit int64
264		}{
265			{"日号为零", 0, 90},
266			{"日号为负", -3, 90},
267			{"亏损上限为负", 1, -1},
268			{"日号与上限均非法", -1, -1},
269		} {
270			t.Run(tc.name, func(t *testing.T) {
271				recsBefore := len(e.Records())
272				if err := e.StartTradingDay(tc.day, tc.lossLimit); err == nil {
273					t.Fatalf("开日(%d, %d) 必须返回错误", tc.day, tc.lossLimit)
274				}
275				if len(e.Records()) != recsBefore {
276					t.Fatalf("非法开日不得追加记录，实际新增 %d 条", len(e.Records())-recsBefore)
277				}
278				if e.RiskStatus().Open {
279					t.Fatal("非法开日后必须仍处于未开日状态")
280				}
281				if o, _ := e.Order(buyID); o.Status != StatusPartial || o.Filled != 10 || o.Remaining() != 5 {
282					t.Fatalf("非法开日不得改动买单: %+v", o)
283				}
284				if o, _ := e.Order(sellID); o.Status != StatusPending || o.Remaining() != 3 {
285					t.Fatalf("非法开日不得改动卖单: %+v", o)
286				}
287				if e.Cash() != 900 || e.ReservedCash() != 50 || e.Position("A") != 10 ||
288					e.Sellable("A") != 7 {
289					t.Fatalf("非法开日不得改动资金与占用: cash=%d reserved=%d pos=%d sellable=%d",
290						e.Cash(), e.ReservedCash(), e.Position("A"), e.Sellable("A"))
291				}
292				if q, _ := e.CurrentQuote("A"); q.Seq != 1 || q.Price != 10 {
293					t.Fatalf("非法开日后最新报价必须停在 seq1@10: %+v", q)
294				}
295				if !e.HasGap("A") {
296					t.Fatal("非法开日后等待中的 seq3 必须继续等待")
297				}
298				if countRiskRecords(e) != 0 {
299					t.Fatal("非法开日不得产生触线记录")
300				}
301			})
302		}
303	
304		// 修正参数后合法开日：仍按最新已生效报价 seq1 定基准，等待报价不参与。
305		if err := e.StartTradingDay(1, 90); err != nil {
306			t.Fatalf("合法开日必须成功: %v", err)
307		}
308		st := e.RiskStatus()
309		if !st.Open || st.Day != 1 || st.Baseline != 1000 || st.Equity != 1000 ||
310			st.Loss != 0 || st.LossLimit != 90 || st.Restricted {
311			t.Fatalf("非法尝试后合法开日仍应得到基准 1000、亏损 0、未触发: %+v", st)
312		}
313		if !e.HasGap("A") {
314			t.Fatal("合法开日后缺口仍必须保留")
315		}
316	
317		// 补齐后行为与主路径一致：seq2、seq3 依次生效，seq3 触发保护并撤单。
318		n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 20, Price: 10})
319		if err != nil || n != 2 {
320			t.Fatalf("补齐应使 seq2/seq3 依次生效: n=%d err=%v", n, err)
321		}
322		st = e.RiskStatus()
323		if !st.Restricted || st.Equity != 910 || st.Loss != 90 {
324			t.Fatalf("补齐后应在 seq3 触线：净值 910、亏损 90: %+v", st)
325		}
326		if o, _ := e.Order(buyID); o.Status != StatusCanceled || o.Filled != 10 || o.Remaining() != 0 {
327			t.Fatalf("买单剩余 5 股必须被保护撤销、已成交 10 股保留: %+v", o)
328		}
329		if o, _ := e.Order(sellID); o.Status != StatusPending || o.Remaining() != 3 {
330			t.Fatalf("卖单必须保持有效: %+v", o)
331		}
332		if e.Cash() != 900 || e.ReservedCash() != 0 || e.Position("A") != 10 ||
333			e.Sellable("A") != 7 {
334			t.Fatalf("撤单只释放 50 占用：余额 900、持仓 10、卖单占用与可卖 7 不变: "+
335				"cash=%d reserved=%d pos=%d sellable=%d",
336				e.Cash(), e.ReservedCash(), e.Position("A"), e.Sellable("A"))
337		}
338		if countRiskRecords(e) != 1 {
339			t.Fatal("合法交易日只能有一条触线记录，非法尝试不得占用")
340		}
341	}
342

