135		oSell, _ := e.Order(sellA)
136		if oSell.Status != StatusPending || oSell.Side != Sell || oSell.Qty != 2 ||
137			oSell.Limit != 1 || oSell.Remaining() != 2 || oSell.Reason != "" {
138			t.Fatalf("有效卖单必须原样保留、不被风险保护撤销: %+v", oSell)
139		}
140	
141		// 新增记录恰好 3 条：首次触线 → 撤 B 单 → 撤 A 单（编号从大到小）。
142		newRecs := e.Records()[recsBefore21:]
143		if len(newRecs) != 3 {
144			t.Fatalf("调到 20 后应只新增 3 条记录（触线、撤B、撤A），实际 %d 条: %+v", len(newRecs), newRecs)
145		}
146	
147		// 1) 触线记录：明确由调整上限引发；基准、净值、亏损、新上限齐备。
148		tr := newRecs[0]
149		if tr.Kind != RecordRiskTriggered {
150			t.Fatalf("第一条应为当日首次触线记录: %+v", tr)
151		}
152		if tr.RiskTrigger != RiskTriggerAdjustLimit || tr.RiskRefSeq != 0 || tr.RiskRefMoment != 0 {
153			t.Fatalf("触线来源必须是调限额且不关联报价或成交: trigger=%s ref=%d moment=%d",
154				tr.RiskTrigger, tr.RiskRefSeq, tr.RiskRefMoment)
155		}
156		if tr.RiskDay != 1 || tr.RiskBaseline != 1004 || tr.RiskEquity != 984 ||
157			tr.RiskLoss != 20 || tr.RiskLimit != 20 || !tr.RiskRestrict {
158			t.Fatalf("触线记录必须固化基准1004、净值984、亏损20、新上限20: %+v", tr)
159		}
160		// 估值报价只包含有持仓的 A；只有待成交买单的 B 不得计入。
161		if len(tr.RiskQuoteRefs) != 1 {
162			t.Fatalf("估值报价应只包含有持仓的 A，实际 %+v", tr.RiskQuoteRefs)
163		}
164		if tr.RiskQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 2, Moment: 30, Price: 5}) {
165			t.Fatalf("触线估值报价必须定位 A 序号2、时刻30、价格5: %+v", tr.RiskQuoteRefs)
166		}
167		if !strings.Contains(tr.Reason, "调限额") || !strings.Contains(tr.Reason, "亏损 20") ||
168			!strings.Contains(tr.Reason, "上限 20") {
169			t.Fatalf("触线原因必须写明由调限额引发、亏损 20 与上限 20: %q", tr.Reason)
170		}
171		if countRiskRecords(e) != 1 {
172			t.Fatal("一个交易日只能有一条触线记录")
173		}
174	
175		// 2) 撤销 B 单：取消 2 份，保留触线时亏损 20、新上限 20；报价快照为 B 的 seq1。
176		crB := newRecs[1]
177		if crB.Kind != RecordCanceled || crB.OrderID != bidB || crB.Symbol != "B" || crB.Side != Buy {
178			t.Fatalf("第二条应为 B 买单撤销记录: %+v", crB)
179		}
180		if crB.Qty != 2 || crB.Filled != 0 || crB.Remaining != 2 {
181			t.Fatalf("B 撤销记录必须说明取消了 2 份: %+v", crB)
182		}
183		if !crB.QuoteValid || crB.QuoteSeq != 1 || crB.QuoteMoment != 20 || crB.QuotePrice != 20 {
184			t.Fatalf("B 撤销记录的报价快照应锚定 B 序号1、时刻20、价格20: %+v", crB)
185		}
186		if crB.RiskDay != 1 || crB.RiskBaseline != 1004 || crB.RiskEquity != 984 ||
187			crB.RiskLoss != 20 || crB.RiskLimit != 20 || !crB.RiskRestrict {
188			t.Fatalf("B 撤销记录必须保留触线时亏损 20 与新上限 20: %+v", crB)
189		}
190		if !strings.Contains(crB.Reason, "亏损 20") || !strings.Contains(crB.Reason, "上限 20") {
191			t.Fatalf("B 撤销原因必须以亏损 20、上限 20 解释: %q", crB.Reason)
192		}
193	
194		// 3) 撤销 A 单：取消剩余 6 份（已成交 4 份保留），同样固化亏损 20、新上限 20；
195		// 报价快照为 A 的 seq2@时刻30 价格5。
196		crA := newRecs[2]
197		if crA.Kind != RecordCanceled || crA.OrderID != bidA || crA.Symbol != "A" || crA.Side != Buy {
198			t.Fatalf("第三条应为 A 买单撤销记录: %+v", crA)
199		}
200		if crA.Qty != 10 || crA.Filled != 4 || crA.Remaining != 6 {
201			t.Fatalf("A 撤销记录必须保留总量 10、已成交 4，并说明取消了 6 份: %+v", crA)
202		}
203		if !crA.QuoteValid || crA.QuoteSeq != 2 || crA.QuoteMoment != 30 || crA.QuotePrice != 5 {
204			t.Fatalf("A 撤销记录的报价快照应锚定 A 序号2、时刻30、价格5: %+v", crA)
205		}
206		if crA.RiskDay != 1 || crA.RiskBaseline != 1004 || crA.RiskEquity != 984 ||
207			crA.RiskLoss != 20 || crA.RiskLimit != 20 || !crA.RiskRestrict {
208			t.Fatalf("A 撤销记录必须保留触线时亏损 20 与新上限 20: %+v", crA)
209		}
210		if !strings.Contains(crA.Reason, "亏损 20") || !strings.Contains(crA.Reason, "上限 20") {
211			t.Fatalf("A 撤销原因必须以亏损 20、上限 20 解释: %q", crA.Reason)
212		}
213	
214		// 全部记录中不得出现卖单撤销。
215		for _, r := range e.Records() {
216			if r.Kind == RecordCanceled && r.OrderID == sellA {
217				t.Fatalf("有效卖单 %d 不得被风险保护撤销: %+v", sellA, r)
218			}
219		}
220	
221		// 限制持续：即使完全合规（资金、持仓限额、行情连续均满足），新买单也被拒绝，
222		// 拒绝记录固化当日亏损与上限。
223		recsBeforeBuy := len(e.Records())
224		if _, err := e.Buy("A", 1, 1); err == nil {
225			t.Fatal("触线限制后合规新买单也必须拒绝")
226		}
227		rj := e.Records()[recsBeforeBuy]
228		if rj.Kind != RecordRejected || rj.Symbol != "A" || rj.Side != Buy {
229			t.Fatalf("新买单应留下拒绝记录: %+v", rj)
230		}
231		if rj.RiskDay != 1 || rj.RiskLoss != 20 || rj.RiskLimit != 20 || !rj.RiskRestrict {
232			t.Fatalf("拒绝记录必须固化触线后风险快照: %+v", rj)
233		}
234	
235		// 已被撤销的买单不能再撤销或借修改恢复。
236		if err := e.Cancel(bidB); err == nil {
237			t.Fatal("已被风险保护撤销的 B 买单不能再次撤销")
238		}
239		if err := e.Modify(bidA, 12, 10); err == nil {
240			t.Fatal("已被风险保护撤销的 A 买单不能借修改恢复")
241		}
242	
243		// 调高上限不能解除整日限制，也不产生第二条触线记录。
244		if err := e.SetLossLimit(100); err != nil {
245			t.Fatal(err)
246		}
247		if !e.RiskStatus().Restricted {
248			t.Fatal("触线后调高上限不得解除限制")
249		}
250		if countRiskRecords(e) != 1 {
251			t.Fatal("限制保留期间不得重复产生触线记录")
252		}
253	}
254	
255	// TestRiskLowerLimitJustAboveLossChangesNothing 单独钉住边界：
256	// 新上限严格大于当前亏损（21 > 20）时，即使是“下调”，也不得触线或撤单。
257	func TestRiskLowerLimitJustAboveLossChangesNothing(t *testing.T) {
258		e, bidA, bidB, sellA := adjustLimitSetup(t)
259	
260		recsBefore := len(e.Records())
261		if err := e.SetLossLimit(21); err != nil {
262			t.Fatal(err)
263		}
264		if st := e.RiskStatus(); st.Restricted || st.LossLimit != 21 {
265			t.Fatalf("亏损 20 低于新上限 21 时不应触线: %+v", st)
266		}
267		// 两笔买单与卖单全部保持原状态与占用。
268		if o, _ := e.Order(bidA); o.Status != StatusPartial || o.Remaining() != 6 {
269			t.Fatalf("A 买单应保持有效、剩余 6: %+v", o)
270		}
271		if o, _ := e.Order(bidB); o.Status != StatusPending || o.Remaining() != 2 {
272			t.Fatalf("B 买单应保持有效、剩余 2: %+v", o)
273		}
274		if o, _ := e.Order(sellA); o.Status != StatusPending || o.Remaining() != 2 {
275			t.Fatalf("A 卖单应保持有效: %+v", o)
276		}
277		if e.Cash() != 964 || e.ReservedCash() != 100 || e.AvailableCash() != 864 {
278			t.Fatalf("未触线时现金占用必须保持原值: cash=%d reserved=%d available=%d",
279				e.Cash(), e.ReservedCash(), e.AvailableCash())
280		}
281		if len(e.Records()) != recsBefore || countRiskRecords(e) != 0 {
282			t.Fatal("新上限高于当前亏损时不得追加触线、撤销或任何记录")
283		}
284	
285		// 未触线下新买单只要合规仍可接受（占用现金 1，可用 863）。
286		newBid := mustBuy(t, e, "B", 1, 1)
287		if e.ReservedCash() != 101 {
288			t.Fatalf("未触线时新买单应正常占用现金: reserved=%d", e.ReservedCash())
289		}
290		// 触线撤单仍按编号从大到小：新买单（编号更大）先撤，再撤 B、A。
291		if err := e.SetLossLimit(20); err != nil {
292			t.Fatal(err)
293		}
294		var canceled []int64
295		sawTrigger := false
296		for _, r := range e.Records()[recsBefore:] {
297			if r.Kind == RecordRiskTriggered {
298				sawTrigger = true
299				continue
300			}
301			if sawTrigger && r.Kind == RecordCanceled {
302				canceled = append(canceled, r.OrderID)
303			}
304		}
305		want := []int64{newBid, bidB, bidA}
306		if len(canceled) != len(want) {
307			t.Fatalf("触线应撤销 3 笔买单，实际 %v", canceled)
308		}
309		for i := range want {
310			if canceled[i] != want[i] {
311				t.Fatalf("撤单必须按订单编号从大到小 %v，实际 %v", want, canceled)
312			}
313		}
314	}
315	
316	// TestRiskNegativeLimitAdjustmentRejectedAndKeepsState 覆盖负上限调整：
317	// 报错且不改变风险状态、订单或占用，不追加触线、撤销记录。
318	func TestRiskNegativeLimitAdjustmentRejectedAndKeepsState(t *testing.T) {
319		e, bidA, bidB, sellA := adjustLimitSetup(t)
320	
321		// 触线前：负上限报错，上限保持 100，无任何记录追加。
322		recsBefore := len(e.Records())
323		if err := e.SetLossLimit(-1); err == nil {
324			t.Fatal("负亏损上限必须报错")
325		}
326		st := e.RiskStatus()
327		if !st.Open || st.LossLimit != 100 || st.Restricted || st.Equity != 984 || st.Loss != 20 {
328			t.Fatalf("负上限失败后风险状态必须保持: %+v", st)
329		}
330		if e.Cash() != 964 || e.ReservedCash() != 100 || e.AvailableCash() != 864 {
331			t.Fatalf("负上限失败后资金占用必须保持: cash=%d reserved=%d available=%d",
332				e.Cash(), e.ReservedCash(), e.AvailableCash())
333		}
334		if o, _ := e.Order(bidA); o.Status != StatusPartial || o.Remaining() != 6 {
335			t.Fatalf("负上限失败后 A 买单必须保持有效: %+v", o)
336		}
337		if o, _ := e.Order(bidB); o.Status != StatusPending || o.Remaining() != 2 {
338			t.Fatalf("负上限失败后 B 买单必须保持有效: %+v", o)
339		}
340		if o, _ := e.Order(sellA); o.Status != StatusPending {
341			t.Fatalf("负上限失败后 A 卖单必须保持有效: %+v", o)
342		}
343		if len(e.Records()) != recsBefore {
344			t.Fatal("负上限失败不得追加任何记录（含拒绝记录）")
345		}
346		if countRiskRecords(e) != 0 {
347			t.Fatal("负上限失败不得追加触线记录")
348		}
349	
350		// 触线后再调负上限：限制、新上限 20、撤单结果与记录数同样保持不变。
351		if err := e.SetLossLimit(20); err != nil {
352			t.Fatal(err)
353		}
354		triggeredRecs := len(e.Records())
355		if !e.RiskStatus().Restricted {
356			t.Fatal("前置必须已触线")
357		}
358		if err := e.SetLossLimit(-5); err == nil {
359			t.Fatal("触线后负上限同样必须报错")
360		}
361		st2 := e.RiskStatus()
362		if !st2.Restricted || st2.LossLimit != 20 || st2.Loss != 20 {
363			t.Fatalf("触线后负上限失败不得改变风险状态: %+v", st2)
364		}
365		if e.Cash() != 964 || e.ReservedCash() != 0 || e.Position("A") != 4 || e.Sellable("A") != 2 {
366			t.Fatalf("触线后负上限失败不得改变资金与持仓: cash=%d reserved=%d pos=%d sellable=%d",
367				e.Cash(), e.ReservedCash(), e.Position("A"), e.Sellable("A"))
368		}
369		if len(e.Records()) != triggeredRecs {
370			t.Fatal("触线后负上限失败不得追加任何记录")
371		}
372		if countRiskRecords(e) != 1 {
373			t.Fatal("负上限失败不得追加触线记录")
374		}
375	}
